// MIT. Exact retained Woo basket/catalog contracts; original SF88 owns payment.
import {createHash} from 'node:crypto';
import {need, operation} from '../sf88-operator-buyer-cli/config.mjs';
import {fields, publicUrl, reference} from './buyer.mjs';

export const BASKET_SCHEMA = 'stellar-forge.sf104.checkout-handoff.v2';
export const CATALOG_SCHEMA = 'stellar-forge.sf104.basket-catalog.v1';
export const BASKET_ADMISSION_SCHEMA = 'stellar-forge.sf104.checkout-admission.v2';
export const MAX_LINES = 20, MAX_UNITS = 100;
const MAX_ATOMIC = (1n << 127n) - 1n;
const HASH = /^[a-f0-9]{64}$/;
const normalize = value => Array.isArray(value) ? value.map(normalize) : value && typeof value === 'object'
  ? Object.fromEntries(Object.keys(value).sort().map(key => [key, normalize(value[key])])) : value;
export const canonical = value => JSON.stringify(normalize(value));
export const basketDigest = value => createHash('sha256').update(canonical(value)).digest('hex');
const same = (a,b) => canonical(a) === canonical(b);
const exact = (value, keys, code) => {
  fields(value, keys, code);
  need(keys.every(key => Object.hasOwn(value,key)),code); return value;
};
const name = value => typeof value === 'string' && value.length >= 1 && value.length <= 240 &&
  !/[\x00-\x1f\x7f]/.test(value);
const compareReference = (a,b) => a.length - b.length || a.localeCompare(b);
export function storeMinor(value) {
  need(typeof value === 'string' && /^(0|[1-9][0-9]{0,17})(?:\.[0-9]{1,8})?$/.test(value),
    'WOO_BASKET_STORE_AMOUNT_INVALID');
  const [whole,fraction=''] = value.split('.');
  return BigInt(whole + fraction.padEnd(8,'0'));
}
export function storeDecimal(value) {
  need(typeof value === 'bigint' && value >= 0n,'WOO_BASKET_STORE_AMOUNT_INVALID');
  const whole = value / 100000000n, fraction = String(value % 100000000n).padStart(8,'0').replace(/0+$/,'');
  const result = String(whole) + (fraction ? '.' + fraction : '');
  storeMinor(result); return result;
}
function atomic(value) {
  need(typeof value === 'string' && /^[1-9][0-9]{0,38}$/.test(value) && BigInt(value) <= MAX_ATOMIC,
    'WOO_BASKET_ATOMIC_INVALID');
  return BigInt(value);
}
function quantity(value) {
  need(typeof value === 'string' && /^[1-9][0-9]{0,2}$/.test(value) && Number(value) <= MAX_UNITS,
    'WOO_BASKET_QUANTITY_INVALID');
  return Number(value);
}
function payment(expect, url, method) {
  exact(expect,['scheme','network','asset','payTo','maxAtomic','maxTimeoutSeconds'],'WOO_BASKET_TERMS_INVALID');
  atomic(expect.maxAtomic);
  need(Number.isInteger(expect.maxTimeoutSeconds) && expect.maxTimeoutSeconds >= 1 && expect.maxTimeoutSeconds <= 86400,
    'WOO_BASKET_TIMEOUT_INVALID');
  operation({intentId:'woo-basket-catalog',url,method,expect});
}
export function validateBasketCatalog(raw) {
  exact(raw,['schema','storeOrigin','routeId','url','method','limits','products','catalogDigest'],'WOO_BASKET_CATALOG_FIELDS_INVALID');
  need(raw.schema === CATALOG_SCHEMA && typeof raw.routeId === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(raw.routeId),
    'WOO_BASKET_CATALOG_INVALID');
  const store = publicUrl(raw.storeOrigin,'WOO_STORE_ORIGIN_INVALID'), url = publicUrl(raw.url,'WOO_BASKET_URL_INVALID');
  need(raw.storeOrigin === store.origin && !store.search && store.pathname === '/' && !url.search &&
    !raw.url.endsWith('?') && raw.url === url.href && ['GET','HEAD'].includes(raw.method),'WOO_BASKET_URL_INVALID');
  exact(raw.limits,['maxLines','maxUnits'],'WOO_BASKET_LIMITS_INVALID');
  need(raw.limits.maxLines === MAX_LINES && raw.limits.maxUnits === MAX_UNITS,'WOO_BASKET_LIMITS_INVALID');
  need(Array.isArray(raw.products) && raw.products.length >= 1 && raw.products.length <= 64,'WOO_BASKET_PRODUCTS_INVALID');
  let previous, first;
  for(const p of raw.products) {
    exact(p,['productId','name','storefront','expect'],'WOO_BASKET_PRODUCT_FIELDS_INVALID');
    need(reference(p.productId) && (!previous || compareReference(previous,p.productId) < 0) && name(p.name),
      'WOO_BASKET_PRODUCT_INVALID'); previous = p.productId;
    exact(p.storefront,['currency','total'],'WOO_BASKET_STORE_FIELDS_INVALID');
    need(typeof p.storefront.currency === 'string' && /^[A-Z][A-Z0-9]{2,9}$/.test(p.storefront.currency) &&
      storeMinor(p.storefront.total) > 0n && storeDecimal(storeMinor(p.storefront.total)) === p.storefront.total,
      'WOO_BASKET_STORE_AMOUNT_INVALID');
    payment(p.expect,raw.url,raw.method);
    const identity = [p.storefront.currency,p.expect.scheme,p.expect.network,p.expect.asset,p.expect.payTo];
    need(!first || same(first,identity),'WOO_BASKET_ONE_PAYMENT_IDENTITY_REQUIRED'); first ??= identity;
  }
  const body = structuredClone(raw); delete body.catalogDigest;
  need(HASH.test(raw.catalogDigest) && basketDigest(body) === raw.catalogDigest,'WOO_BASKET_CATALOG_DIGEST_MISMATCH');
  return structuredClone(raw);
}
export function basketTerms(h) {
  const url = new URL(h.operation.url); url.search = '';
  return {storeOrigin:h.storeOrigin,orderReference:h.orderReference,catalogDigest:h.catalogDigest,
    routeId:h.routeId,storefront:h.storefront,items:h.items,
    resource:{url:url.href,method:h.operation.method},expect:h.operation.expect};
}
/** Called after the original handoff validator checks URL, identity and SF88 terms. */
export function validateBasketHandoff(h) {
  need(h.schema === BASKET_SCHEMA && HASH.test(h.catalogDigest) && HASH.test(h.basketDigest) &&
    Array.isArray(h.items) && h.items.length >= 1 && h.items.length <= MAX_LINES,'WOO_BASKET_HANDOFF_INVALID');
  let previous, units = 0, store = 0n, total = 0n;
  const products = new Set();
  for(const line of h.items) {
    exact(line,['lineId','productId','quantity','name','unitStoreTotal','lineStoreTotal',
      'unitAmountAtomic','lineAmountAtomic','maxTimeoutSeconds','downloads'],'WOO_BASKET_LINE_FIELDS_INVALID');
    need(reference(line.lineId) && reference(line.productId) && !products.has(line.productId) &&
      (!previous || compareReference(previous,line.lineId) < 0) && name(line.name),'WOO_BASKET_LINE_IDENTITY_INVALID');
    previous = line.lineId; products.add(line.productId);
    const q = quantity(line.quantity); units += q;
    const unitStore = storeMinor(line.unitStoreTotal), lineStore = storeMinor(line.lineStoreTotal);
    const unitAmount = atomic(line.unitAmountAtomic), lineAmount = atomic(line.lineAmountAtomic);
    need(unitStore > 0n && lineStore === unitStore * BigInt(q) && lineAmount === unitAmount * BigInt(q) &&
      storeDecimal(unitStore) === line.unitStoreTotal && storeDecimal(lineStore) === line.lineStoreTotal,
      'WOO_BASKET_LINE_TOTAL_MISMATCH');
    need(Number.isInteger(line.maxTimeoutSeconds) && line.maxTimeoutSeconds >= 1 && line.maxTimeoutSeconds <= 86400 &&
      Array.isArray(line.downloads) && line.downloads.length <= 64 && line.downloads.every(name),
      'WOO_BASKET_LINE_DELIVERY_INVALID');
    store += lineStore; total += lineAmount;
  }
  need(units <= MAX_UNITS && store === storeMinor(h.storefront.total) && total === atomic(h.operation.expect.maxAtomic) &&
    h.operation.expect.maxTimeoutSeconds === Math.min(...h.items.map(x=>x.maxTimeoutSeconds)),
    'WOO_BASKET_AGGREGATE_MISMATCH');
  need(basketDigest(basketTerms(h)) === h.basketDigest,'WOO_BASKET_DIGEST_MISMATCH');
  const u = new URL(h.operation.url);
  need([...u.searchParams.keys()].length === 3 && u.searchParams.get('sf104_basket') === h.basketDigest,
    'WOO_BASKET_RESOURCE_MISMATCH');
  return h;
}
/** Merchant-authenticated Woo quote must also match an operator-retained catalog. */
export function matchBasketCatalog(h, catalog) {
  validateBasketHandoff(h);
  need(h.catalogDigest === catalog.catalogDigest && h.storeOrigin === catalog.storeOrigin &&
    h.routeId === catalog.routeId && h.operation.method === catalog.method &&
    new URL(h.operation.url).origin + new URL(h.operation.url).pathname === catalog.url,
    'WOO_BASKET_CATALOG_MISMATCH');
  const byProduct = new Map(catalog.products.map(p=>[p.productId,p]));
  for(const line of h.items) {
    const p = byProduct.get(line.productId);
    need(p && p.storefront.currency === h.storefront.currency && p.storefront.total === line.unitStoreTotal &&
      p.expect.maxAtomic === line.unitAmountAtomic && p.expect.maxTimeoutSeconds === line.maxTimeoutSeconds &&
      ['scheme','network','asset','payTo'].every(key=>p.expect[key] === h.operation.expect[key]),
      'WOO_BASKET_UNIT_MAPPING_CHANGED');
  }
  return h;
}

#!/usr/bin/env node
// MIT. Woo order handoff -> the original SF88 operation and private workspace.
import {createHash} from 'node:crypto';
import {constants} from 'node:fs';
import {open, unlink} from 'node:fs/promises';
import {isAbsolute, resolve} from 'node:path';
import {isIP} from 'node:net';
import {fileURLToPath} from 'node:url';
import {operation, execution, need} from '../sf88-operator-buyer-cli/config.mjs';
import {BASKET_SCHEMA, validateBasketHandoff} from './basket.mjs';

export const HANDOFF_SCHEMA = 'stellar-forge.sf104.checkout-handoff.v1';
export const sha256 = value => createHash('sha256').update(value).digest('hex');
export const isObject = value => value !== null && typeof value === 'object' && !Array.isArray(value);
export function fields(value, allowed, code) {
  need(isObject(value) && Object.keys(value).every(key => allowed.includes(key)), code);
  return value;
}
export function publicUrl(value, code = 'PUBLIC_HTTPS_URL_REQUIRED') {
  need(typeof value === 'string' && value.length <= 2048 && !/[\x00-\x20\x7f]/.test(value), code);
  let url;
  try { url = new URL(value); } catch { need(false, code); }
  const host = url.hostname.toLowerCase();
  need(url.protocol === 'https:' && !url.username && !url.password && !url.hash &&
    (!url.port || url.port === '443') && !isIP(host.replace(/^\[|\]$/g, '')) &&
    host.includes('.') && !['localhost','local','localdomain','internal','home.arpa'].some(
      name => host === name || host.endsWith('.' + name)) &&
    host.length <= 253 && host.split('.').every(part => /^[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/.test(part)), code);
  return url;
}
export function reference(value) {
  return typeof value === 'string' && /^[1-9][0-9]{0,17}$/.test(value);
}
export function generation(value) {
  return Number.isInteger(value) && value >= 1 && value <= 2147483647;
}
function money(value) {
  return typeof value === 'string' && /^(?:0|[1-9][0-9]{0,17})(?:\.[0-9]{1,8})?$/.test(value) &&
    /[1-9]/.test(value);
}

/** Downloaded merchant data is never allowed to choose a signer, wallet,
 * operator, filesystem path, arbitrary request header or payment intent ID. */
export function validateHandoff(raw) {
  const basket = raw?.schema === BASKET_SCHEMA;
  const h = fields(raw, ['schema','storeOrigin','orderReference','attemptGeneration','routeId',
    'createdAt','storefront','operation', ...(basket ? ['catalogDigest','basketDigest','items'] : ['productId'])], 'WOO_HANDOFF_FIELDS_INVALID');
  need((h.schema === HANDOFF_SCHEMA || basket) && reference(h.orderReference) && generation(h.attemptGeneration) &&
    (basket || reference(h.productId)) &&
    typeof h.routeId === 'string' && /^[A-Za-z0-9_-]{1,64}$/.test(h.routeId), 'WOO_HANDOFF_IDENTITY_INVALID');
  const store = publicUrl(h.storeOrigin, 'WOO_STORE_ORIGIN_INVALID');
  need(store.pathname === '/' && !store.search &&
    (h.storeOrigin === store.origin || h.storeOrigin === store.origin + '/'), 'WOO_STORE_ORIGIN_INVALID');
  need(typeof h.createdAt === 'string' && /^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{3})?(?:Z|\+00:00)$/.test(h.createdAt) &&
    Number.isFinite(Date.parse(h.createdAt)), 'WOO_CREATED_AT_INVALID');
  fields(h.storefront, ['currency','total'], 'WOO_STOREFRONT_INVALID');
  need(typeof h.storefront.currency === 'string' && /^[A-Z][A-Z0-9]{2,9}$/.test(h.storefront.currency) &&
    money(h.storefront.total), 'WOO_STOREFRONT_INVALID');
  const request = fields(h.operation, ['url','method','expect','orderReference'], 'WOO_OPERATION_FIELDS_INVALID');
  const url = publicUrl(request.url, 'WOO_RESOURCE_INVALID');
  need(['GET','HEAD'].includes(request.method) && request.orderReference === h.orderReference &&
    [...url.searchParams.keys()].length === (basket ? 3 : 2) && url.searchParams.get('sf98_order') === h.orderReference &&
    url.searchParams.get('sf104_attempt') === String(h.attemptGeneration),
    'WOO_ORDER_RESOURCE_MISMATCH');
  const expect = fields(request.expect, ['scheme','network','asset','payTo','maxAtomic','maxTimeoutSeconds'],
    'WOO_PAYMENT_FIELDS_INVALID');
  need(typeof expect.maxAtomic === 'string' && /^[1-9][0-9]*$/.test(expect.maxAtomic) &&
    Number.isInteger(expect.maxTimeoutSeconds) && expect.maxTimeoutSeconds >= 1 &&
    expect.maxTimeoutSeconds <= 86400 &&
    ['asset','payTo'].every(key => typeof expect[key] === 'string' && expect[key].length <= 128 &&
      expect[key].length >= 3 && !/[\x00-\x20\x7f]/.test(expect[key])), 'WOO_PAYMENT_FIELDS_INVALID');
  if (basket) {
    need(h.storeOrigin === store.origin, 'WOO_STORE_ORIGIN_INVALID');
    validateBasketHandoff(h);
  }
  const intentId = 'woo:' + sha256(store.origin).slice(0, 24) + ':' + h.orderReference + ':g' + h.attemptGeneration;
  // This is the SAME original order-reference/approved-URL/header contract.
  operation({...request, intentId});
  return structuredClone({...h, storeOrigin:store.origin});
}

export function prepareBuyer(raw) {
  const h = validateHandoff(raw);
  const intentId = 'woo:' + sha256(h.storeOrigin).slice(0, 24) + ':' + h.orderReference + ':g' + h.attemptGeneration;
  const op = operation({...h.operation, intentId});
  return {handoff:h, config:{operation:op, captureBody:false}, handoffSha256:sha256(JSON.stringify(h))};
}

/** Reuse an explicitly chosen original workspace without loading keys or a
 * signer. The downloaded handoff cannot replace its trusted operator settings. */
export async function prepareForWorkspace(prepared, path) {
  need(typeof path === 'string' && isAbsolute(path) && resolve(path) === path,
    'WORKSPACE_ABSOLUTE_PATH_REQUIRED');
  const {openWorkspace} = await import('../sf88-operator-buyer-cli/workspace.mjs');
  const workspace = await openWorkspace(['--dir', path]);
  const trusted = workspace.config, terms = prepared.config.operation.expect;
  need(['scheme','network','asset','payTo'].every(key => terms[key] === trusted.operation.expect[key]) &&
    ['network','asset','payTo'].every(key => terms[key] === workspace.manifest.signer[key]),
    'WOO_WORKSPACE_PAYMENT_TERMS_MISMATCH');
  need(BigInt(terms.maxAtomic) <= BigInt(trusted.operation.expect.maxAtomic) &&
    BigInt(terms.maxAtomic) <= BigInt(workspace.manifest.signer.maxAtomic), 'WOO_WORKSPACE_CAP_EXCEEDED');
  const config = {...prepared.config, operator:structuredClone(trusted.operator),
    signerModule:trusted.signerModule, evidenceDir:trusted.evidenceDir, trustedPayer:trusted.trustedPayer,
    ...(trusted.buyerTransport === undefined ? {} : {buyerTransport:structuredClone(trusted.buyerTransport)})};
  execution(config); // Includes original transport-origin binding.
  return {...prepared, config, workspace:path};
}

/** No network or signer import. Repeated exports for one shop/order/generation
 * recover the same original intent even when the filename or formatting varies.
 * Only an audited merchant reset advances the generation for a new approval. */
export async function readHandoff(path) {
  need(typeof path === 'string' && isAbsolute(path), 'HANDOFF_ABSOLUTE_PATH_REQUIRED');
  const file = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const info = await file.stat();
    need(info.isFile() && info.size > 0 && info.size <= 65536, 'WOO_HANDOFF_FILE_INVALID');
    const raw = await file.readFile();
    need(raw.length <= 65536, 'WOO_HANDOFF_FILE_INVALID');
    return validateHandoff(JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)));
  } finally { await file.close(); }
}

export async function writeBuyerConfig(path, prepared) {
  need(typeof path === 'string' && isAbsolute(path) && resolve(path) === path, 'OUTPUT_ABSOLUTE_PATH_REQUIRED');
  const data = Buffer.from(JSON.stringify(prepared.config, null, 2) + '\n');
  let file;
  try { file = await open(path, 'wx', 0o600); }
  catch (error) {
    if (error.code !== 'EEXIST') throw error;
    const previous = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
    try {
      const info = await previous.stat();
      need(info.isFile() && info.size <= 65536 &&
        (process.platform === 'win32' || (info.mode & 0o077) === 0), 'EXISTING_BUYER_CONFIG_UNSAFE');
      const bytes = await previous.readFile();
      need(bytes.length <= 65536 && bytes.equals(data), 'EXISTING_BUYER_CONFIG_CONFLICT');
      return 'EXISTING_MATCH';
    } finally { await previous.close(); }
  }
  try { await file.writeFile(data); await file.sync(); }
  catch (error) { await file.close().catch(() => {}); await unlink(path).catch(() => {}); throw error; }
  await file.close();
  return 'CREATED';
}

const USAGE = `node buyer.mjs inspect --handoff /absolute/woo-order.json
node buyer.mjs prepare --handoff /absolute/woo-order.json --out /absolute/new-review.json
node buyer.mjs prepare --handoff /absolute/woo-order.json --workspace /absolute/existing-workspace --out /absolute/new-inbox-config.json

prepare writes a private ORIGINAL SF88 review configuration. It makes no network
request and cannot sign or pay. Review it with ../sf88-operator-buyer-cli/cli.mjs
--review --config FILE, then use that CLI's original --init-workspace command.
Keep the same ledger for recovery; each merchant-approved order generation has one
deterministic intent. Only an audited merchant reset can permit a new generation.
The merchant's signed live-order admission checks precede native verification.
With --workspace, prepare copies only that validated workspace's trusted operator
settings into a new original inbox configuration; it never loads keys or a signer.
Enqueue and execute that file through the original SF88 queue with the same workspace.
After native payment, Woo delivery remains in the original merchant review queue.`;

export async function main(args = process.argv.slice(2)) {
  if (args.length === 1 && args[0] === '--help') { console.log(USAGE); return; }
  const action = args[0], options = new Map();
  need(['inspect','prepare'].includes(action), 'WOO_BUYER_ACTION_REQUIRED');
  for (let i = 1; i < args.length; i += 2) {
    need(['--handoff','--out','--workspace'].includes(args[i]) && !options.has(args[i]) &&
      typeof args[i+1] === 'string' && !args[i+1].startsWith('--'), 'WOO_BUYER_ARGUMENT_INVALID');
    options.set(args[i], args[i+1]);
  }
  need(options.has('--handoff') && (action === 'prepare' ? options.has('--out') :
    !options.has('--out') && !options.has('--workspace')),
    'WOO_BUYER_ARGUMENT_REQUIRED');
  let prepared = prepareBuyer(await readHandoff(resolve(options.get('--handoff'))));
  if (options.has('--workspace')) prepared = await prepareForWorkspace(prepared, resolve(options.get('--workspace')));
  const output = action === 'prepare' ? resolve(options.get('--out')) : null;
  const disposition = output ? await writeBuyerConfig(output, prepared) : null;
  const result = {status:output ? 'ORIGINAL_SF88_REVIEW_PREPARED' : 'WOO_ORDER_REVIEW',
    storeOrigin:prepared.handoff.storeOrigin, orderReference:prepared.handoff.orderReference,
    attemptGeneration:prepared.handoff.attemptGeneration,
    ...(prepared.handoff.items ? {items:prepared.handoff.items, catalogDigest:prepared.handoff.catalogDigest,
      basketDigest:prepared.handoff.basketDigest} : {productId:prepared.handoff.productId}), routeId:prepared.handoff.routeId,
    storefront:prepared.handoff.storefront, operation:prepared.config.operation,
    handoffSha256:prepared.handoffSha256, ...(output ? {output, disposition} : {}),
    ...(prepared.workspace ? {workspace:prepared.workspace} : {}),
    payment:'ORIGINAL_BUYER_APPROVAL_REQUIRED', delivery:'ORIGINAL_WOO_MERCHANT_REVIEW', networkRequests:0};
  console.log(JSON.stringify(result, null, 2)); return result;
}
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url))
  main().catch(error => {
    console.error(JSON.stringify({error:/^[A-Z0-9_]+$/.test(error.code ?? '') ? error.code : 'WOO_BUYER_COMMAND_FAILED',
      automaticPaymentRetry:false})); process.exitCode = 1;
  });

// MIT. Native merchant review composes the original Woo, SF98 and SF86 stores.
import {randomUUID} from 'node:crypto';
import {readdir} from 'node:fs/promises';
import {join, resolve} from 'node:path';
import {fields, publicUrl, reference} from './buyer.mjs';
import {openOutbox, SCHEMA as OUTBOX_SCHEMA} from '../sf98-merchant-delivery/outbox.mjs';
import {createPublicHttpsFetch} from '../sf31-buyer-client/public-transport.mjs';
import {reconcileRpc, reconcileReportedReceipt} from '../sf86-rpc-transfer-reconcile/verify.mjs';
import {checkOriginalTerms, checkReportedTerms, networkProfile} from '../sf86-rpc-transfer-reconcile/terms.mjs';
import {originalRecordFromEvidence} from '../sf86-rpc-transfer-reconcile/cli.mjs';
import {createOfficialEventDecoder} from '../sf43-agent-commerce/verify.mjs';
import {absolute, need, object, digest, now, privateDirectory, readBytes, readJson,
  parseJson, writeBytes, writeJson, exists, jsonBytes, safeCode} from '../sf88-operator-buyer-cli/node/store.mjs';

export const CONFIG_SCHEMA = 'stellar-forge.sf104.merchant-operator.v1';
export const ORDER_SCHEMA = 'stellar-forge.sf104.merchant-order.v1';
export const REFUND_ORDER_SCHEMA = 'stellar-forge.sf104.merchant-refunds.v1';
export const INPUT_SCHEMA = 'stellar-forge.sf104.merchant-review-input.v1';
export const REVIEW_SCHEMA = 'stellar-forge.sf104.merchant-review.v1';
export const RELEASE_SCHEMA = 'stellar-forge.sf104.merchant-release.v1';
const HASH = /^[0-9a-f]{64}$/;
const REVIEW_ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/;
const MAX_RESPONSE = 1024 * 1024;
const MAX_RECORD = 4 * 1024 * 1024;

export function compileOperator(raw) {
  fields(raw, ['schema', 'siteUrl', 'usernameEnv', 'applicationPasswordEnv', 'outbox', 'workspace',
    'timeoutMs', 'allowLocal'], 'WOO_OPERATOR_FIELDS_INVALID');
  need(raw.schema === CONFIG_SCHEMA, 'WOO_OPERATOR_SCHEMA_INVALID');
  need(raw.allowLocal === undefined || typeof raw.allowLocal === 'boolean', 'WOO_OPERATOR_LOCAL_OPTION_INVALID');
  let url;
  try { url = new URL(raw.siteUrl); } catch { need(false, 'WOO_OPERATOR_SITE_INVALID'); }
  const local = raw.allowLocal === true && url.protocol === 'http:' && url.hostname === '127.0.0.1' &&
    !!url.port && Number(url.port) >= 1 && Number(url.port) <= 65535;
  if (!local) url = publicUrl(raw.siteUrl, 'WOO_OPERATOR_SITE_INVALID');
  need(!url.search && !url.hash && !url.username && !url.password && !/%2f|%5c|\.\./i.test(url.pathname),
    'WOO_OPERATOR_SITE_INVALID');
  for (const name of ['usernameEnv', 'applicationPasswordEnv']) {
    need(typeof raw[name] === 'string' && /^[A-Z][A-Z0-9_]{1,80}$/.test(raw[name]), 'WOO_OPERATOR_AUTH_ENV_REQUIRED');
  }
  const timeoutMs = raw.timeoutMs ?? 15000;
  need(Number.isSafeInteger(timeoutMs) && timeoutMs >= 100 && timeoutMs <= 60000, 'WOO_OPERATOR_TIMEOUT_INVALID');
  const siteUrl = url.href.replace(/\/$/, '');
  return Object.freeze({schema:CONFIG_SCHEMA, siteUrl, usernameEnv:raw.usernameEnv,
    applicationPasswordEnv:raw.applicationPasswordEnv, outbox:absolute(raw.outbox),
    workspace:absolute(raw.workspace), timeoutMs, allowLocal:local,
    restUrl:siteUrl + '/wp-json/stellar-forge/v1/merchant/orders/'});
